def solve(wall):
    edges = {}
    for row in wall:
        curr = 0
        for i in range(len(row) - 1):
            curr += row[i]
            edges[curr] = edges.get(curr, 0) + 1
    if not edges: return len(wall)
    return len(wall) - max(edges.values())

